module TopModule (
  input clk,
  input x,
  input [2:0] y,
  output reg Y0,
  output reg z
);

always @(*) begin
  case (y)
    3'd0: Y0 = clk & x;
    3'd1: Y0 = clk | x;
    3'd2: Y0 = clk ^ x;
    3'd3: Y0 = ~(clk & x);
    3'd4: Y0 = ~(clk | x);
    3'd5: Y0 = ~(clk ^ x);
    3'd6: Y0 = clk;
    3'd7: Y0 = x;
    default: Y0 = 1'b0;
  endcase
end

always @(*) begin
  case (y)
    3'd0: z = ~(clk & x);
    3'd1: z = ~(clk | x);
    3'd2: z = ~(clk ^ x);
    3'd3: z = clk & x;
    3'd4: z = clk | x;
    3'd5: z = clk ^ x;
    3'd6: z = ~clk;
    3'd7: z = ~x;
    default: z = 1'b0;
  endcase
end

endmodule

