module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

wire sel1 = clk_a & clk_b;
wire sel0 = arstn | brstn;

always @(*) begin
	case ({sel1, sel0})
		2'b00: dataout = data_in;
		2'b01: dataout = ~data_in;
		2'b10: dataout = data_in + {3'b0, data_en};
		2'b11: dataout = data_in - {3'b0, data_en};
		default: dataout = 4'b0;
	endcase
end

endmodule

